import {type CookiesOptions, type NextAuthOptions, type Theme} from 'next-auth'
import {PrismaAdapter} from './skill-next-auth-prisma-adapter'
import {sendVerificationRequest} from './send-verification-request'
import {prisma} from '@skillrecordings/database'
import EmailProvider from 'next-auth/providers/email'
import {NextApiRequest, NextApiResponse} from 'next'
import {Inngest} from 'inngest'
import {sanityClient} from '../lib/sanity-client'
import {z} from 'zod'

async function getUser(userId: string) {
  return prisma.user.findUnique({
    where: {id: userId},
    select: {
      roles: true,
      id: true,
      name: true,
      purchases: {
        select: {
          id: true,
          status: true,
          country: true,
          merchantChargeId: true,
          productId: true,
          createdAt: true,
          totalAmount: true,
          bulkCouponId: true,
          bulkCoupon: {
            select: {
              maxUses: true,
              usedCount: true,
            },
          },
          product: {
            select: {
              id: true,
              name: true,
            },
          },
        },
      },
    },
  })
}

export const createOptions = (config: {
  req?: NextApiRequest
  res?: NextApiResponse
  theme: Theme
  providers?: any[]
  debug?: boolean
  cookies?: Partial<CookiesOptions>
  skillCookieDomain?: string
}) => {
  return defaultNextAuthOptions(config)
}

export function defaultNextAuthOptions(options: {
  theme: Theme
  debug?: boolean
  req?: NextApiRequest
  res?: NextApiResponse
  providers?: any[]
  cookies?: Partial<CookiesOptions>
  skillCookieDomain?: string
}): NextAuthOptions {
  const {
    theme,
    debug,
    req,
    res,
    cookies,
    providers = [],
    skillCookieDomain,
  } = options
  return {
    secret: [REDACTED],
    events: {
      signIn: async ({user, account, profile}) => {
        if (process.env.INNGEST_EVENT_KEY) {
          const inngest = new Inngest({
            id:
              process.env.INNGEST_APP_NAME ||
              process.env.NEXT_PUBLIC_SITE_TITLE ||
              'Sanity Products Webhook',
            eventKey: process.env.INNGEST_EVENT_KEY,
          })

          console.log('user', user)

          await inngest.send({
            name: 'user/login',
            data: {account, profile, user},
            user,
          })
        }
      },
      signOut: async () => {
        if (res) {
          res.setHeader(
            'Set-Cookie',
            `skill=0; Path=/; SameSite=Lax; Expires=Thu, 01 Jan 1970 00:00:00 GMT${
              skillCookieDomain ? `; Domain=${skillCookieDomain}` : ''
            }`,
          )
        }
      },
      createUser: async ({user}) => {
        if (process.env.INNGEST_EVENT_KEY) {
          const inngest = new Inngest({
            id:
              process.env.INNGEST_APP_NAME ||
              process.env.NEXT_PUBLIC_SITE_TITLE ||
              'Sanity Products Webhook',
            eventKey: process.env.INNGEST_EVENT_KEY,
          })

          await inngest.send({
            name: 'user/created',
            data: {user},
            user,
          })
        }
      },
      linkAccount: async ({user, account, profile}) => {
        if (process.env.INNGEST_EVENT_KEY) {
          const inngest = new Inngest({
            id:
              process.env.INNGEST_APP_NAME ||
              process.env.NEXT_PUBLIC_SITE_TITLE ||
              'Skill Recordings Product',
            eventKey: process.env.INNGEST_EVENT_KEY,
          })

          await inngest.send({
            name: 'user/oauth-provider-account-linked',
            data: {account, profile},
            user,
          })
        }
      },
    },
    session: {
      strategy: 'jwt',
    },
    cookies,
    theme,
    debug,
    adapter: PrismaAdapter(prisma),
    jwt: {
      secret: [REDACTED],
    },
    providers: [
      EmailProvider({
        server: {
          host: process.env.EMAIL_SERVER_HOST,
          port: process.env.EMAIL_SERVER_PORT,
          auth: {
            user: process.env.POSTMARK_KEY,
            pass: process.env.POSTMARK_KEY,
          },
        },
        from: process.env.NEXT_PUBLIC_SUPPORT_EMAIL,
        sendVerificationRequest,
      }),
      ...providers,
    ],
    callbacks: {
      async session({session, token}) {
        if (token?.id) {
          const user = await getUser(token.id as string)

          const dbProducts =
            user?.purchases.map((purchase) => purchase.product) || []

          const parsedModules = z
            .object({
              free: z.array(z.string()).default([]),
              paid: z.array(z.string()).default([]),
            })
            .safeParse(
              await sanityClient.fetch(
                `{
              "free": *[_type == 'module' && moduleType == 'tutorial'].slug.current,
              "paid": array::unique(*[_type == 'product' && productId in $productIds].modules[]->slug.current)
            }`,
                {
                  productIds: dbProducts.map((product) => product.id),
                },
              ),
            )

          if (res && parsedModules.success) {
            const {free, paid} = parsedModules.data
            res.setHeader(
              'Set-Cookie',
              `skill=${[...free, ...paid].join(',')}; Path=/; SameSite=Lax ${
                skillCookieDomain ? `; Domain=${skillCookieDomain}` : ''
              }`,
            )
          }

          if (user && session.user) {
            const {roles, purchases} = user
            session.user.purchases = purchases
            session.user.role = roles
            // session.purchases = purchases
            // session.role = roles
            token.purchases = purchases
            token.role = roles
          }
        } else {
          token.purchases = []
          // session.user.purchases = []
        }

        return session
      },
      async jwt({token, user: authUser, trigger, session}) {
        if (trigger === 'update' && token?.id) {
          const user = await getUser(token.id as string)
          token.name = user?.name
        }
        if (authUser) {
          const user = await getUser(authUser.id)
          if (user) {
            const {roles, id, purchases} = user
            token.id = id
            token.purchases = purchases
            token.role = roles || 'user'
          }
        } else if (req?.url === '/api/auth/session?update' && token?.id) {
          const user = await getUser(token.id as string)
          if (user) {
            const {roles, id, purchases} = user
            token.id = id
            token.purchases = purchases
            token.role = roles || 'user'
          }
        }
        return token
      },
    },
    pages: {
      signIn: '/login',
      error: '/error',
      verifyRequest: '/check-your-email',
    },
  }
}

import {PrismaClient, Prisma} from '@skillrecordings/database'
import type {Adapter} from 'next-auth/adapters'
import {addSeconds, isAfter} from 'date-fns'

export function PrismaAdapter(p: PrismaClient): Adapter {
  return {
    // @ts-ignore
    createUser: (data) => p.user.create({data}),
    getUser: (id) => p.user.findUnique({where: {id}}),
    getUserByEmail: (email) => p.user.findUnique({where: {email}}),
    async getUserByAccount(provider_providerAccountId) {
      const account = await p.account.findUnique({
        where: {provider_providerAccountId},
        select: {user: true},
      })
      return account?.user ?? null
    },
    // @ts-ignore
    updateUser: ({id, ...data}) => p.user.update({where: {id}, data}),
    deleteUser: (id) => p.user.delete({where: {id}}),
    linkAccount: (data) => p.account.create({data}) as any,
    unlinkAccount: (provider_providerAccountId) =>
      p.account.delete({where: {provider_providerAccountId}}) as any,
    // @ts-ignore
    async getSessionAndUser(sessionToken) {
      const userAndSession = await p.session.findUnique({
        // @ts-ignore
        where: {sessionToken},
        include: {user: true},
      })
      if (!userAndSession) return null
      // @ts-ignore
      const {user, ...session} = userAndSession
      return {user, session}
    },
    // @ts-ignore
    createSession: (data) => p.session.create({data}),
    // @ts-ignore
    updateSession: (data) =>
      // @ts-ignore
      p.session.update({where: {sessionToken: [REDACTED]}, data}),
    // @ts-ignore
    deleteSession: (sessionToken) => p.session.delete({where: {sessionToken}}),
    // @ts-ignore
    async createVerificationToken(data) {
      // @ts-ignore
      const {id: _, ...verificationToken} = await p.verificationToken.create({
        data: {...data, createdAt: new Date()},
      })
      return verificationToken
    },
    // @ts-ignore
    async useVerificationToken(identifier_token) {
      try {
        const token = await p.verificationToken.findFirst({
          where: identifier_token,
        })

        if (token?.createdAt) {
          const TIMEOUT_IN_SECONDS = 90
          const expireMultipleClicks = addSeconds(
            token.createdAt,
            TIMEOUT_IN_SECONDS,
          )
          const now = new Date()

          if (isAfter(expireMultipleClicks, now)) {
            // @ts-ignore
            const {id: _, ...verificationToken} = token
            return verificationToken
          } else {
            // @ts-ignore
            const {id: _, ...verificationToken} =
              await p.verificationToken.delete({
                where: {identifier_token},
              })
            return verificationToken
          }
        }
      } catch (error) {
        // If token already used/deleted, just return null
        // https://www.prisma.io/docs/reference/api-reference/error-reference#p2025
        if ((error as Prisma.PrismaClientKnownRequestError).code === 'P2025')
          return null
        throw error
      }
    },
  }
}

import NextAuth, {DefaultSession} from 'next-auth'

type Resolve<T> = T extends Function ? T : {[K in keyof T]: T[K]}

type User = Resolve<
  {
    role?: string
    purchases?: any[]
  } & DefaultSession['user']
>

declare module 'next-auth' {
  /**
   * Returned by `useSession`, `getSession` and received as a prop on the
   * `SessionProvider` React Context
   */
  interface Session {
    user?: User
  }
}

