/* -------------------------------------------------------------------------------------------------
 * Resources
 * -----------------------------------------------------------------------------------------------*/

Resources.displayName = RESOURCES_NAME

const RESOURCE_NAME = 'Resource'

type ResourceElement = React.ElementRef<typeof Primitive.li>

interface ResourceProps extends PrimitiveLiProps {
  /**
   * Path is appended to the lesson link (e.g. /module/lesson/**problem**)
   */
  path?: string
  type?: string
}

const useResourceLinkBuilder = (
  modulePath?: string,
  resourcePath?: string,
  ignoreSections?: boolean,
) => {
  const {section, module, lesson} = useLesson()

  const pathname = `/[module]/${
    section && !ignoreSections ? `[section]/` : ``
  }[lesson]`
  const href = `/${module.slug.current}/${
    section && !ignoreSections ? `${section.slug}/` : ``
  }${lesson.slug}`

  return {
    resourcePathname:
      '/' +
      modulePath +
      (resourcePath ? pathname + `/${resourcePath}` : pathname),
    resourceHref:
      '/' + modulePath + (resourcePath ? href + `/${resourcePath}` : href),
  }
}

/* -------------------------------------------------------------------------------------------------
 * Resource
 * -----------------------------------------------------------------------------------------------*/

/**
 * Represents a resource that is linked to a lesson. Such as a **problem, exercise, or solution**.
 * @param {string} path (optional) gets appended to the lesson link (e.g. /module/lesson/**problem**)
 * @constructor
 */
const Resource = React.forwardRef<ResourceElement, ResourceProps>(
  (props: ScopedProps<ResourceProps>, forwardedRef) => {
    const {__scopeCollection, path, children, ...resourceProps} = props
    const {lesson, section} = useLesson()
    const {
      module,
      path: modulePath,
      ignoreSections,
    } = useCollectionContext(COLLECTION_NAME, __scopeCollection)

    const router = useRouter()

    const {resourcePathname, resourceHref} = useResourceLinkBuilder(
      modulePath,
      path,
      ignoreSections,
    )
    const isActive = router.asPath === resourceHref

    return (
      <Primitive.li
        {...resourceProps}
        className={cn('[&>a]:px-[34px] [&>a]:py-2', resourceProps.className)}
        ref={forwardedRef}
      >
        <Link
          data-active={isActive.toString()}
          href={{
            pathname: resourcePathname,
            query: {
              module: module.slug.current,
              lesson: lesson.slug,
              ...(section && !ignoreSections && {section: section.slug}),
            },
          }}
          passHref
          onClick={() => {
            track(`clicked lesson resource in navigator`, {
              module: module.slug.current,
              lesson: lesson.slug,
              ...(section && {section: section.slug}),
              location: router.query.lesson,
              moduleType: module.moduleType,
              lessonType: lesson._type,
            })
          }}
        >
          {children}
        </Link>
      </Primitive.li>
    )
  },
)

Resource.displayName = RESOURCE_NAME

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const getLessonHref = (
  lesson: LessonType,
  module: Module,
  section?: SectionType,
  ignoreSections?: boolean,
) => {
  const pathname = `/${pluralize(module.moduleType)}/[module]/${
    section && !ignoreSections ? '[section]/' : ''
  }[lesson]`
  const query = {
    lesson: lesson.slug,
    module: module.slug.current,
    ...(section && {section: section.slug}),
  }
  return {pathname, query}
}

const useScrollToActiveLesson = (
  activeElementToScrollTo: React.RefObject<HTMLDivElement>,
  scrollContainerRef?: React.RefObject<HTMLDivElement>,
) => {
  React.useEffect(() => {
    const activeElementOffset = activeElementToScrollTo?.current?.offsetTop

    activeElementOffset &&
      scrollContainerRef?.current?.scrollTo({
        top: activeElementOffset,
      })
  }, [activeElementToScrollTo, scrollContainerRef])
}

const getLessonChildren = (children: React.ReactNode, props: LessonProps) => {
  let lessonChildren: React.ReactElement[] = []

  React.Children.forEach(children, (child) => {
    if (React.isValidElement<LessonsProps>(child) && child.type === Lessons) {
      React.Children.forEach(child.props.children, (lessonChild) => {
        if (
          React.isValidElement<LessonProps>(lessonChild) &&
          lessonChild.type === Lesson
        ) {
          const clonedLesson = React.cloneElement(lessonChild, {
            ...props,
          })
          lessonChildren.push(clonedLesson)
        }
      })
    }
  })

  return lessonChildren
}

const getSectionChildren = (children: React.ReactNode, props: SectionProps) => {
  let sectionChildren: React.ReactElement[] = []

  React.Children.forEach(children, (child) => {
    if (React.isValidElement<SectionsProps>(child) && child.type === Sections) {
      React.Children.forEach(child.props.children, (sectionChild) => {
        if (
          React.isValidElement<SectionProps>(sectionChild) &&
          sectionChild.type === Section
        ) {
          const clonedSection = React.cloneElement(sectionChild, {
            ...props,
          })
          sectionChildren.push(clonedSection)
        }
      })
    }
  })

  return sectionChildren
}

