    },
    {
      type: 'text',
      name: 'firstName',
      message: `What is our partner's first name?`,
      initial: 'Badass',
    },
    {
      type: 'text',
      name: 'lastName',
      message: `What is our partner's last name?`,
      initial: 'Dev',
    },
    {
      type: 'text',
      name: 'twitter',
      message: `What is our partner's twitter? (no @)`,
      initial: 'twitterHandle',
